'use strict';

// Minimal argv parser: --key value | --key=value | --flag | --no-flag |
// -abc clusters | repeated keys -> arrays | "--" terminator -> rest |
// numeric coercion unless key listed in opts.strings.

function looksNumeric(v) {
  if (typeof v !== 'string' || v.trim() === '') return false;
  // Allow integers, decimals, exponents, leading +/-; reject things like "12abc"
  return /^[+-]?(\d+\.?\d*|\.\d+)([eE][+-]?\d+)?$/.test(v.trim());
}

function coerce(value, strings) {
  if (!looksNumeric(value)) return value;
  if (strings.has('*')) return value; // opt out globally, convenience
  return Number(value);
}

function isFlagLike(arg) {
  return typeof arg === 'string' && arg.length > 1 && arg[0] === '-';
}

function parse(argv, opts = {}) {
  const strings = new Set(opts.strings || []);
  const defaults = opts.default || {};
  const result = { _: [] };
  const args = Array.isArray(argv) ? argv.slice() : [];

  let i = 0;
  while (i < args.length) {
    const arg = args[i];

    // Terminator: everything after goes to rest array
    if (arg === '--') {
      for (i = i + 1; i < args.length; i++) result._.push(args[i]);
      break;
    }

    if (isFlagLike(arg)) {
      if (arg.startsWith('--')) {
        const body = arg.slice(2);
        const eq = body.indexOf('=');
        let key, inlineValue;
        const hasInline = eq !== -1;
        key = hasInline ? body.slice(0, eq) : body;

        let value;
        if (hasInline) {
          value = coerce(body.slice(eq + 1), strings);
        } else {
          const next = args[i + 1];
          if (key.startsWith('no-')) {
            key = key.slice(3);
            value = false;
          } else if (next !== undefined && !isFlagLike(next)) {
            value = coerce(next, strings);
            i++; // consume the value
          } else {
            value = true; // boolean flag (next is another flag or end)
          }
        }
        assign(result, key, value);
        i++;
        continue;
      }

      // Short cluster: -abc
      const cluster = arg.slice(1);
      for (const ch of cluster) {
        assign(result, ch, true);
      }
      i++;
      continue;
    }

    // Bare positional
    result._.push(arg);
    i++;
  }

  // Defaults for keys never seen
  for (const [k, v] of Object.entries(defaults)) {
    if (!(k in result)) result[k] = v;
  }
  return result;
}

function assign(result, key, value) {
  if (key in result) {
    if (Array.isArray(result[key])) result[key].push(value);
    else result[key] = [result[key], value];
  } else {
    result[key] = value;
  }
}

module.exports = { parse };

