'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const { parse } = require('./parseargs.js');

test('long option with separate value', () => {
  assert.equal(parse(['--port', '8080']).port, 8080); // coerced to number
});

test('long option with = value', () => {
  assert.equal(parse(['--host=localhost']).host, 'localhost');
  assert.equal(parse(['--level=3']).level, 3);
});

test('boolean flag', () => {
  assert.strictEqual(parse(['--verbose']).verbose, true);
});

test('boolean flag does not swallow a following flag', () => {
  const r = parse(['--verbose', '--debug']);
  assert.strictEqual(r.verbose, true);
  assert.strictEqual(r.debug, true);
});

test('negation via --no-flag', () => {
  assert.strictEqual(parse(['--no-cache']).cache, false);
});

test('last one wins: --no-flag then later --flag', () => {
  const r = parse(['--no-color', '--other', 'x', '--color']);
  assert.strictEqual(r.color, true);
});

test('last one wins: --flag then later --no-flag', () => {
  const r = parse(['--color', '--no-color']);
  assert.strictEqual(r.color, false);
});

test('short flags', () => {
  assert.strictEqual(parse(['-v']).v, true);
});

test('short cluster expands to individual booleans', () => {
  const r = parse(['-abc']);
  assert.strictEqual(r.a, true);
  assert.strictEqual(r.b, true);
  assert.strictEqual(r.c, true);
});

test('repeated options collect into arrays', () => {
  const r = parse(['--tag', 'a', '--tag=b', '--tag', 'c']);
  assert.deepEqual(r.tag, ['a', 'b', 'c']);
});

test('-- terminator fills rest array', () => {
  const r = parse(['--name', 'joe', '--', '--not-a-flag', '-x', 'plain']);
  assert.equal(r.name, 'joe');
  assert.deepEqual(r._, ['--not-a-flag', '-x', 'plain']);
});

test('bare positionals go to rest array', () => {
  assert.deepEqual(parse(['file1.txt', 'file2.txt'])._, ['file1.txt', 'file2.txt']);
});

test('automatic numeric coercion', () => {
  const r = parse(['--n', '42', '--pi=3.14', '--neg', '-7', '--sci', '1e3']);
  assert.strictEqual(r.n, 42);
  assert.strictEqual(r.pi, 3.14);
  assert.strictEqual(r.neg, -7);
  assert.strictEqual(r.sci, 1000);
});

test('opts.strings opts out of coercion per key', () => {
  const r = parse(['--id', '007', '--zip', '90210'], { strings: ['id', 'zip'] });
  assert.strictEqual(r.id, '007');   // leading zero preserved
  assert.strictEqual(r.zip, '90210');
});

test('non-numeric values stay strings even without opts.strings', () => {
  const r = parse(['--name', 'alice', '--ver', '1.2.3']);
  assert.strictEqual(r.name, 'alice');
  assert.strictEqual(r.ver, '1.2.3'); // not coercible, stays string
});

test('mixed repetition upgrades scalar to array', () => {
  const r = parse(['--k', '1', '--k', '2']);
  assert.ok(Array.isArray(r.k));
  assert.deepEqual(r.k, [1, 2]);
});

